use std::sync::Mutex;

pub struct Inventory {
    items: Mutex<Vec<String>>,
}

impl Inventory {
    pub fn new() -> Self {
        Inventory { items: Mutex::new(Vec::new()) }
    }

    pub fn add(&self, item: &str) {
        self.items.lock().unwrap().push(item.to_string());
    }

    pub fn count(&self) -> usize {
        self.items.lock().unwrap().len()
    }

    /// Add the item only if it isn't present yet; returns whether it was added.
    pub fn add_unique(&self, item: &str) -> bool {
        let items = self.items.lock().unwrap();
        if items.contains(&item.to_string()) {
            return false;
        }
        // BUG: self.add() locks the SAME mutex we're still holding -
        // std::sync::Mutex is not reentrant, so this deadlocks forever.
        self.add(item);
        true
    }
}

test_setup_files.tests/deadlock_test.rs:
use conc_case::Inventory;
use std::sync::mpsc;
use std::thread;
use std::time::Duration;

#[test]
fn add_unique_does_not_deadlock() {
    let (tx, rx) = mpsc::channel();
    thread::spawn(move || {
        let inv = Inventory::new();
        assert!(inv.add_unique("hammer"));
        assert!(!inv.add_unique("hammer"));
        assert!(inv.add_unique("nail"));
        assert_eq!(inv.count(), 2);
        tx.send(inv.count()).unwrap();
    });
    // watchdog: a deadlocked add_unique never sends, and we fail fast
    match rx.recv_timeout(Duration::from_secs(5)) {
        Ok(count) => assert_eq!(count, 2),
        Err(_) => panic!("add_unique deadlocked (watchdog fired after 5s)"),
    }
}

